```ts
export interface PublicRecord {
  id: string;
  heading: string;
  details: string;
}

export interface PresenterState {
  loading: boolean;
  record: PublicRecord | null;
  error: string | null;
}

export type RecordLoader = (id: string) => PublicRecord;

export class RecordPresenter {
  private state: PresenterState = { loading: false, record: null, error: null };

  public constructor(private readonly loader: RecordLoader) {}

  public load(id: string): void {
    const key = id.trim();
    if (key.length === 0) throw new TypeError("id must not be empty");
    this.state.loading = true;
    this.state.record = null;
    try {
      const loaded = this.loader(key);
      this.state.record = { ...loaded };
    } catch (error: unknown) {
      this.state.error = error instanceof Error ? error.message : "Unknown error";
    } finally {
      this.state.loading = false;
    }
  }

  public snapshot(): PresenterState {
    return {
      ...this.state,
      record: this.state.record ? { ...this.state.record } : null
    };
  }
}
```

