import { RecordPresenter } from "./solution";
import type { PublicRecord, PresenterState, RecordLoader } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${message}: expected ${e}, received ${a}`);
}

function throwsType(action: () => void, message: string): void {
  let caught: unknown;
  try { action(); } catch (error: unknown) { caught = error; }
  if (!(caught instanceof TypeError)) throw new Error(`${message}: expected TypeError`);
}

let calls = 0;
let observedLoading = false;
let presenter!: RecordPresenter;
const source: PublicRecord = { id: "item", heading: "Heading", details: "Details" };
const loader: RecordLoader = (id: string): PublicRecord => {
  calls += 1;
  observedLoading = presenter.snapshot().loading;
  assert(id === "item", "loader receives trimmed id");
  return source;
};
presenter = new RecordPresenter(loader);

equal(presenter.snapshot(), { loading: false, record: null, error: null }, "initial state");
presenter.load("  item  ");
assert(calls === 1, "loader called exactly once");
assert(observedLoading, "loading is true during loader call");
equal(presenter.snapshot(), { loading: false, record: source, error: null }, "successful state");
source.heading = "Caller changed source";
assert(presenter.snapshot().record?.heading === "Heading", "successful record is copied");

const snap1: PresenterState = presenter.snapshot();
const snap2 = presenter.snapshot();
assert(snap1 !== snap2, "snapshot object is fresh");
assert(snap1.record !== snap2.record, "snapshot record is fresh");
if (snap1.record) snap1.record.details = "Changed snapshot";
assert(presenter.snapshot().record?.details === "Details", "snapshot record cannot mutate internal state");

const failed = new RecordPresenter((): PublicRecord => { throw new Error("load failed"); });
failed.load("x");
equal(failed.snapshot(), { loading: false, record: null, error: "load failed" }, "Error message is exposed");

const unknownFailure = new RecordPresenter((): PublicRecord => { throw "failure"; });
unknownFailure.load("x");
equal(unknownFailure.snapshot(), { loading: false, record: null, error: "Unknown error" }, "non-Error failure uses fallback message");

let attempt = 0;
let duringSecond: PresenterState | null = null;
let retry!: RecordPresenter;
retry = new RecordPresenter((id: string): PublicRecord => {
  attempt += 1;
  if (attempt === 1) throw new Error("first error");
  duringSecond = retry.snapshot();
  return { id, heading: "Recovered", details: "OK" };
});
retry.load("first");
retry.load("second");
equal(duringSecond, { loading: true, record: null, error: null }, "new attempt clears prior record and error before loader");
equal(retry.snapshot(), {
  loading: false,
  record: { id: "second", heading: "Recovered", details: "OK" },
  error: null
}, "successful retry remains clear of old error");

let invalidCalls = 0;
const invalidPresenter = new RecordPresenter((id: string): PublicRecord => {
  invalidCalls += 1;
  return { id, heading: "H", details: "D" };
});
throwsType(() => invalidPresenter.load(" \t "), "empty id rejected");
assert(invalidCalls === 0, "invalid load does not call loader");
assert(invalidPresenter.snapshot().loading === false, "loading remains false after invalid load");

